-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_POLICY_PREMIUM_HEAD
--   anchor      : HUB_POLICY
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Premium Head Code + Coverage Reference + Section + Adjusted Indicator
--   feeders     : 3 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        'GROSS_PREMIUM' as PREMIUM_HEAD_CODE,
        coalesce(nullif(trim(BENEFIT_CODE),''),'') as COVERAGE_REFERENCE,
        'POLICY' as SECTION,
        'N' as ADJUSTED_INDICATOR,
        PREMIUM as BASE_AMOUNT,
        null::varchar as NET_HEAD_PREMIUM,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_BENEFITS' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_benefits') }}
    where HUB_POLICY_K0__EMIT
    union all
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        'BASE_PREMIUM' as PREMIUM_HEAD_CODE,
        'ALL' as COVERAGE_REFERENCE,
        'POLICY' as SECTION,
        'N' as ADJUSTED_INDICATOR,
        MEMBER_LEVEL_PREMIUM_BEFORE_COL as BASE_AMOUNT,
        null::varchar as NET_HEAD_PREMIUM,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_pv') }}
    where HUB_POLICY_K0__EMIT
    union all
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        'BASE_PREMIUM' as PREMIUM_HEAD_CODE,
        coalesce(nullif(trim(COVER),''),'') || '@' || coalesce(nullif(trim(MEMBER_NAME),''),'') as COVERAGE_REFERENCE,
        'POLICY' as SECTION,
        'N' as ADJUSTED_INDICATOR,
        BASE_PREMIUM as BASE_AMOUNT,
        GROSS_PREMIUM as NET_HEAD_PREMIUM,
        'MAXI_HLTH_UWR_VW_DATA_PREMIUM_CALCULATION_DETAILS' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_premium_calculation_dtl') }}
    where HUB_POLICY_K0__EMIT
)), hashed as (select *,
        case when BASE_AMOUNT is not null or NET_HEAD_PREMIUM is not null
             then md5(upper(coalesce(BASE_AMOUNT::varchar,'') || '||' || coalesce(NET_HEAD_PREMIUM::varchar,'')))
        end as SAT_POLICY_PREMIUM_HEAD_HASHDIFF
    from feeders)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_PREMIUM_HEAD_HASHDIFF is not null
  and PREMIUM_HEAD_CODE is not null
  and COVERAGE_REFERENCE is not null
  and SECTION is not null
  and ADJUSTED_INDICATOR is not null
